    for flight in Flight.objects.all():
        flight.seat_layout = ''
        flight.business_fare = Decimal('0')
        flight.premium_economy_fare = Decimal('0')
        flight.save(update_fields=['seat_layout', 'business_fare', 'premium_economy_fare'])


